class Solution {
public:
    bool uniqueOccurrences(vector<int>& arr) {
        map<int, int> cnt;
        for (int x : arr) cnt[x]++;
        set<int> seen;
        for (auto& [v, c] : cnt) {
            if (seen.count(c)) return false;
            seen.insert(c);
        }
        return true;
    }
};
